import re


def eval_expression(expr):
    """Evaluate an arithmetic expression with +, -, *, /, and parentheses."""

    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    # Tokenize numbers, operators, and parentheses.
    token_pattern = re.compile(r"""
        \s*
        (
            (?:\d+(?:\.\d*)?|\.\d+)  # number
            | [()+\-*/]               # operator or parenthesis
        )
    """, re.VERBOSE)

    tokens = []
    pos = 0

    while pos < len(expr):
        match = token_pattern.match(expr, pos)
        if not match:
            raise ValueError(f"Invalid character at position {pos}")

        token = match.group(1)
        if token[0].isdigit() or token[0] == ".":
            token = float(token) if "." in token else int(token)

        tokens.append(token)
        pos = match.end()

    index = 0

    def peek():
        return tokens[index] if index < len(tokens) else None

    def consume(expected=None):
        nonlocal index
        token = peek()

        if token is None:
            raise ValueError("Unexpected end of expression")
        if expected is not None and token != expected:
            raise ValueError(f"Expected {expected!r}, got {token!r}")

        index += 1
        return token

    def parse_expression():
        value = parse_term()

        while peek() in ("+", "-"):
            operator = consume()
            right = parse_term()
            value = value + right if operator == "+" else value - right

        return value

    def parse_term():
        value = parse_factor()

        while peek() in ("*", "/"):
            operator = consume()
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        token = peek()

        # Support unary plus and minus, including forms like -(2 + 3).
        if token == "+":
            consume("+")
            return parse_factor()
        if token == "-":
            consume("-")
            return -parse_factor()

        if token == "(":
            consume("(")
            value = parse_expression()
            consume(")")
            return value

        if isinstance(token, (int, float)):
            return consume()

        raise ValueError(f"Unexpected token: {token!r}")

    if not tokens:
        raise ValueError("Expression cannot be empty")

    result = parse_expression()

    if index != len(tokens):
        raise ValueError(f"Unexpected token: {peek()!r}")

    return result
```

Example:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-2 * (3 + 4)"))     # -14
```

